<script setup lang="ts">
import {type Dossier,type Procedure,type UserInfo,statusNames,statusClass,fmtDate,procName} from '~/composables/useCommune'
import {Search,FileText,ArrowRight,CalendarDays,Ticket,BookOpen,Bot,Send,Building2,Layers3,ShieldCheck,Activity,AlertTriangle,Download,CheckCircle2,Plus,LockKeyhole,ClipboardList,RefreshCw,Star,BarChart3,Info,FilePlus2} from 'lucide-vue-next'
const props=defineProps<{section:string;user:UserInfo;stats:Record<string,number>;dossiers:Dossier[];procedures:Procedure[];crossStats:any[];appointments:any[];services:Record<string,string>}>()
const emit=defineEmits<{(e:'refresh'):void;(e:'navigate',value:string):void}>()
const {api,errText}=useCommune()
const busy=ref(false),error=ref(''),notice=ref(''),q=ref(''),filter=ref(''),selected=ref<Dossier|null>(null)
const slot=ref(''),person=ref(''),procedure=ref(''),queueItems=ref<any[]>([]),tenants=ref<any[]>([]),events=ref<any[]>([]),feedbackScore=ref(5),comment=ref(''),feedbackSummary=ref<any>(null)
const tenantCode=ref(''),tenantName=ref(''),aiQuestion=ref(''),aiResponse=ref<any>(null),selectedWiki=ref(''),auditResponse=ref<any>(null),tenantForAudit=ref(''),packFile=ref<File|null>(null)
const role=computed(()=>props.user.role)
const titles:Record<string,string>={new:'Tiếp nhận hồ sơ',dossiers:'Hồ sơ hành chính',appointments:'Lịch hẹn tại quầy',queue:'Quản lý hàng chờ',procedures:'Quy trình & Thủ tục',knowledge:'Kho tri thức',ai:'Trợ lý nghiệp vụ',reports:'Báo cáo & Thống kê',feedback:'Đánh giá & Phản hồi',tenants:'Quản lý đơn vị',packs:'Gói thủ tục & Quy trình',services:'Tình trạng dịch vụ',audit:'Nhật ký & Kiểm toán',notifications:'Thông báo & Nhắc việc',settings:'Cài đặt & Quyền hạn'}
const filtered=computed(()=>props.dossiers.filter(d=>(!q.value||(d.code+d.applicant+d.procedure_code).toLowerCase().includes(q.value.toLowerCase()))&&(!filter.value||d.status===filter.value)))
async function run(action:()=>Promise<any>,success='Thao tác đã hoàn tất'){
 busy.value=true;error.value='';notice.value=''
 try{await action();notice.value=success;emit('refresh')}catch(e:any){error.value=errText(e)}finally{busy.value=false}
}
async function loadExtra(){
 if(props.section==='queue')try{queueItems.value=await api('/api/queue')}catch{}
 if(props.section==='tenants'&&role.value==='sys_admin')try{tenants.value=await api('/api/admin/tenants')}catch{}
 if(props.section==='audit'&&['leader','sys_admin'].includes(role.value)){
  try{events.value=await api('/api/audit/events')}catch{}
  if(role.value==='sys_admin')try{tenants.value=await api('/api/admin/tenants')}catch{}
 }
 if(props.section==='feedback'&&['leader','sys_admin'].includes(role.value))try{feedbackSummary.value=await api('/api/feedback/summary')}catch{}
}
watch(()=>props.section,loadExtra,{immediate:true})
async function openDossier(d:Dossier){
 try{selected.value=await api(`/api/dossiers/${d.id}`)}catch(e:any){error.value=errText(e)}
}
async function book(){await run(async()=>{await api('/api/appointments',{method:'POST',body:{applicant:person.value,procedure_code:procedure.value,slot:new Date(slot.value).toISOString()}})},'Đã ghi nhận lịch hẹn thử nghiệm')}
async function createTicket(){await run(async()=>{await api(`/api/queue/ticket?procedure_code=${encodeURIComponent(procedure.value)}`,{method:'POST'});queueItems.value=await api('/api/queue')},'Đã lấy số thứ tự')}
async function nextTicket(){await run(async()=>{await api('/api/queue/next',{method:'POST'});queueItems.value=await api('/api/queue')},'Đã gọi lượt tiếp theo')}
async function createTenant(){await run(async()=>{await api('/api/admin/tenants',{method:'POST',body:{code:tenantCode.value,name:tenantName.value}});tenants.value=await api('/api/admin/tenants');tenantCode.value='';tenantName.value=''},'Đã tạo đơn vị')}
async function toggleTenant(t:any){await run(async()=>{await api('/api/admin/tenants/'+t.id,{method:'PATCH',body:{status:t.status==='active'?'suspended':'active'}});tenants.value=await api('/api/admin/tenants')},'Đã cập nhật trạng thái đơn vị')}
async function ask(){await run(async()=>{aiResponse.value=await api('/api/ai/ask',{method:'POST',body:{question:aiQuestion.value,procedure_code:procedure.value||null}})},'Đã tra cứu trong wiki')}
async function verify(){await run(async()=>{auditResponse.value=await api('/api/ledger/verify'+(tenantForAudit.value?'?tenant_id='+encodeURIComponent(tenantForAudit.value):''))},'Đã thực hiện đối soát sổ cái')}
async function uploadPack(){
 if(!packFile.value)return
 await run(async()=>{const data=new FormData();data.append('file',packFile.value as File);await api('/api/admin/packs',{method:'POST',body:data})},'Gói thủ tục đã được nhập vào danh mục; việc triển khai BPMN tự động chưa được xác nhận')
}
async function sendFeedback(){await run(async()=>{await api('/api/feedback',{method:'POST',body:{rating:feedbackScore.value,comment:comment.value}});comment.value=''},'Cảm ơn bạn đã gửi đánh giá')}
function exportStats(){
 const rows=props.crossStats.length?props.crossStats:[{unit:'Đơn vị hiện tại',...props.stats}]
 const csv=['Đơn vị,Tổng hồ sơ,Đã hoàn thành,Đang xử lý,Quá hạn',...rows.map(r=>[r.unit,r.total,r.completed,r.processing,r.overdue].join(','))].join('\n')
 const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob)
 const a=document.createElement('a');a.href=url;a.download='communeos-thong-ke-khong-pii.csv';a.click();URL.revokeObjectURL(url)
}
</script>
<template>
 <DossierForm v-if="section==='new'" :procedures="procedures" :role="role" @created="emit('navigate','dossiers');emit('refresh')"/>
 <div v-else class="content-panel"><div class="content-head"><div><span class="eyebrow">COMMUNEOS · {{user.role.toUpperCase()}}</span><h2>{{titles[section]||'Chức năng nghiệp vụ'}}</h2><p>{{section==='reports'?'Số liệu tổng hợp đã loại thông tin định danh trong báo cáo liên xã.':section==='ai'?'Tra cứu nội dung từ kho wiki gói thủ tục, luôn kèm nguồn.':'Không gian tác nghiệp theo vai trò được phân quyền từ API.'}}</p></div><button class="round-icon" title="Làm mới" @click="loadExtra();emit('refresh')"><RefreshCw :size="18"/></button></div>
 <div v-if="section==='dossiers'" class="sections-two"><div><div class="toolbar"><div class="search-field"><Search :size="18"/><input v-model="q" placeholder="Tìm mã hồ sơ, thủ tục, tên..."/></div><select v-model="filter"><option value="">Tất cả trạng thái</option><option v-for="(name,key) in statusNames" :key="key" :value="key">{{name}}</option></select></div>
   <div class="section-list"><button v-for="d in filtered" :key="d.id" class="section-list-row" @click="openDossier(d)"><span class="section-list-icon"><FileText :size="20"/></span><span><strong>{{procName(d.procedure_code,procedures)}}</strong><small>{{d.code}} · {{d.applicant}} · {{fmtDate(d.received_at)}}</small></span><span class="status-pill" :class="statusClass(d.status)">{{statusNames[d.status]}}</span></button><p v-if="!filtered.length" class="empty-mini">Chưa có hồ sơ phù hợp.</p></div></div>
   <div class="detail-card"><DossierDetail :dossier="selected" :role="role" :procedures="procedures" @refresh="openDossier(selected!);emit('refresh')"/></div></div>
 <div v-else-if="section==='appointments'" class="sections-two">
   <div><h3 class="block-title">Lịch hẹn đã ghi nhận</h3><div class="section-list"><div v-for="a in appointments" :key="a.id" class="section-list-row"><span class="section-list-icon"><CalendarDays :size="21"/></span><span><strong>{{a.applicant}}</strong><small>{{fmtDate(a.slot)}} · {{procName(a.procedure_code,procedures)}}</small></span><span class="status-pill success">Đã xác nhận</span></div><div v-if="!appointments.length" class="empty-mini">Chưa có lịch hẹn.</div></div></div>
   <form v-if="['citizen','receptionist'].includes(role)" class="light-form" @submit.prevent="book"><h3>Đặt lịch hẹn mới</h3><label class="field-label">Người đến làm việc<input v-model="person" required minlength="2" placeholder="Họ tên giả lập"/></label><label class="field-label">Thủ tục<select v-model="procedure" required><option value="">Chọn thủ tục</option><option v-for="p in procedures" :value="p.code" :key="p.code">{{p.name}}</option></select></label><label class="field-label">Thời gian<input v-model="slot" type="datetime-local" required/></label><button class="btn primary" :disabled="busy">Xác nhận đặt lịch</button></form></div>
 <div v-else-if="section==='queue'" class="sections-two"><div><h3 class="block-title">Số thứ tự trong ngày</h3><div class="section-list"><div v-for="t in queueItems" :key="t.id" class="section-list-row"><span class="queue-number">{{t.number.toString().padStart(3,'0')}}</span><span><strong>{{procName(t.procedure_code,procedures)}}</strong><small>{{t.date}} · {{t.status}}</small></span><span class="status-pill" :class="t.status==='serving'?'success':'info'">{{t.status==='serving'?'Đang phục vụ':t.status==='waiting'?'Đang chờ':'Đã xong'}}</span></div></div></div>
 <div class="light-form"><h3>Thao tác quầy</h3><label class="field-label">Loại thủ tục<select v-model="procedure"><option value="">Chọn thủ tục</option><option v-for="p in procedures" :value="p.code" :key="p.code">{{p.name}}</option></select></label><button v-if="['citizen','receptionist'].includes(role)" class="btn primary" :disabled="busy||!procedure" @click="createTicket">Lấy số thứ tự</button><button v-if="role==='receptionist'" class="btn subtle" :disabled="busy" @click="nextTicket">Gọi số tiếp theo</button><p class="muted">Độ trễ ước lượng và ưu tiên đặc biệt chưa triển khai.</p></div></div>
 <div v-else-if="section==='procedures'||section==='knowledge'" class="sections-two"><div class="procedure-grid"><button v-for="p in procedures" :key="p.code" class="procedure-card" :class="{selected:selectedWiki===p.code}" @click="selectedWiki=p.code"><BookOpen :size="24"/><strong>{{p.name}}</strong><small>Mã: {{p.code}} · v{{p.version}}</small><small>{{p.required_documents.length}} thành phần hồ sơ</small><span class="text-link">Xem hướng dẫn <ArrowRight :size="15"/></span></button></div>
  <div class="light-form"><h3>{{procName(selectedWiki,procedures)||'Hướng dẫn nghiệp vụ'}}</h3><template v-if="selectedWiki"><p class="wiki-text">{{procedures.find(p=>p.code===selectedWiki)?.wiki||'Mở trang thủ tục để xem chi tiết.'}}</p><small class="muted">Nguồn: packs/{{selectedWiki}}/wiki/huong-dan.md · Nội dung giả lập, cần thẩm định pháp lý.</small></template><div v-else class="empty-mini">Chọn thủ tục bên trái để xem tài liệu liên quan.</div></div></div>
 <div v-else-if="section==='ai'" class="ai-layout"><div class="ai-chat"><div class="ai-intro"><Bot :size="29"/><div><strong>Trợ lý tra cứu CommuneOS</strong><p>Hỏi đáp từ wiki có nguồn · Bản hiện tại chỉ tìm kiếm trích đoạn, không phải mô hình ngôn ngữ.</p></div></div><div class="sample-questions"><button v-for="text in ['Thủ tục khai sinh cần giấy tờ gì?','Quy trình thẩm định gồm những bước nào?','Thời hạn hồ sơ kinh doanh trong bản demo?']" :key="text" @click="aiQuestion=text">{{text}}</button></div>
  <div v-if="aiResponse" class="answer-card"><div><Bot :size="20"/><strong>Thông tin truy xuất</strong></div><p>{{aiResponse.answer}}</p><div v-for="source in aiResponse.sources" :key="source.path" class="source-line"><BookOpen :size="16"/> {{source.title}} · {{source.path}}</div><small class="muted">{{aiResponse.notice||'Không có tài liệu phù hợp. AI không được tự đưa ra quyết định hành chính.'}}</small></div>
  <form class="ai-input" @submit.prevent="ask"><select v-model="procedure"><option value="">Tất cả thủ tục</option><option v-for="p in procedures" :key="p.code" :value="p.code">{{p.name}}</option></select><input v-model="aiQuestion" placeholder="Nhập câu hỏi nghiệp vụ..." required minlength="3"/><button class="btn primary" :disabled="busy"><Send :size="17"/></button></form></div></div>
 <div v-else-if="section==='reports'" class="reports-layout"><div class="report-kpis"><div><small>Tổng số hồ sơ</small><strong>{{stats.total||0}}</strong></div><div><small>Đã giải quyết</small><strong>{{stats.completed||0}}</strong></div><div><small>Đang xử lý</small><strong>{{stats.processing||0}}</strong></div><div><small>Quá hạn</small><strong>{{stats.overdue||0}}</strong></div></div>
  <div v-if="crossStats.length" class="table-scroller"><table class="compact-table"><thead><tr><th>Đơn vị</th><th>Tổng hồ sơ</th><th>Đã giải quyết</th><th>Đang xử lý</th><th>Quá hạn</th><th>Đúng hạn*</th></tr></thead><tbody><tr v-for="r in crossStats" :key="r.tenant_id"><td><Building2 :size="16"/> {{r.unit}}</td><td>{{r.total}}</td><td>{{r.completed}}</td><td>{{r.processing}}</td><td><span class="status-pill" :class="r.overdue?'danger':'success'">{{r.overdue}}</span></td><td>{{r.on_time_rate}}%</td></tr></tbody></table></div>
  <div class="chart-bars"><div v-for="r in (crossStats.length?crossStats:[{unit:'Đơn vị hiện tại',...stats}])" :key="r.unit"><div><strong>{{r.unit}}</strong><small>{{r.total}} hồ sơ</small></div><div class="bar-bg"><span :style="{width:(r.total?Math.round(r.completed/r.total*100):0)+'%'}"></span></div></div></div>
  <button class="btn subtle" @click="exportStats"><Download :size="16"/> Xuất CSV thống kê (không PII)</button><p class="muted">* Tỷ lệ minh họa tính từ số hồ sơ chưa quá hạn/tổng số. Báo cáo pháp lý cần định nghĩa chỉ số riêng.</p></div>
 <div v-else-if="section==='tenants'&&role==='sys_admin'" class="sections-two"><div class="section-list"><div v-for="t in tenants" :key="t.id" class="section-list-row"><span class="section-list-icon"><Building2 :size="21"/></span><span><strong>{{t.name}}</strong><small>{{t.code}} · {{t.id}}</small></span><span class="status-pill" :class="t.status==='active'?'success':'danger'">{{t.status==='active'?'Đang hoạt động':'Đã khóa'}}</span><button class="btn subtle" @click="toggleTenant(t)">{{t.status==='active'?'Khóa':'Mở khóa'}}</button></div></div><form class="light-form" @submit.prevent="createTenant"><h3>Tạo đơn vị mới</h3><label class="field-label">Mã đơn vị<input v-model="tenantCode" required pattern="[a-z0-9-]+" placeholder="xa-moi"/></label><label class="field-label">Tên đơn vị<input v-model="tenantName" required placeholder="Xã Mới (giả lập)"/></label><button class="btn primary" :disabled="busy"><Plus :size="17"/> Thêm đơn vị</button></form></div>
 <div v-else-if="section==='packs'&&role==='sys_admin'" class="sections-two"><div><h3>Gói thủ tục đã đăng ký</h3><div class="section-list"><div v-for="p in procedures" :key="p.code" class="section-list-row"><span class="section-list-icon"><Layers3 :size="19"/></span><span><strong>{{p.name}}</strong><small>{{p.code}} · phiên bản {{p.version}}</small></span><span class="status-pill success">Đã nhập</span></div></div></div><div class="light-form"><h3>Nhập gói thủ tục ZIP</h3><p class="muted">ZIP chứa 5 tệp chuẩn: pack.yaml, process.bpmn, form.schema.json, checklist.dmn, wiki/huong-dan.md.</p><input type="file" accept=".zip" @change="packFile=($event.target as HTMLInputElement).files?.[0]||null"/><button class="btn primary" :disabled="busy||!packFile" @click="uploadPack"><Plus :size="16"/> Kiểm tra và nhập gói</button><p class="muted">Trong phiên bản này, nhập gói lưu cấu hình vào DB; triển khai BPMN lên Flowable là tích hợp bổ sung.</p></div></div>
 <div v-else-if="section==='services'&&role==='sys_admin'" class="service-grid"><div v-for="(value,key) in services" :key="key" class="service-card"><span class="section-list-icon"><Activity :size="23"/></span><div><strong>{{key}}</strong><small>{{value}}</small></div></div><p class="muted">Đây là thông số cấu hình API, chưa phải hệ thống giám sát SLA, CPU hoặc uptime.</p></div>
 <div v-else-if="section==='audit'&&['leader','sys_admin'].includes(role)" class="sections-two"><div><h3>Nhật ký xử lý gần đây</h3><div class="section-list"><div v-for="event in events.slice(0,30)" :key="event.id" class="section-list-row"><span class="section-list-icon"><ShieldCheck :size="18"/></span><span><strong>{{event.action}}</strong><small>{{fmtDate(event.at)}} · {{event.dossier_id.slice(0,8)}}</small></span></div></div></div><div class="light-form"><h3>Đối soát chuỗi băm SHA-256</h3><label v-if="role==='sys_admin'" class="field-label">Chọn đơn vị<select v-model="tenantForAudit"><option value="">Chọn đơn vị</option><option v-for="t in tenants" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button class="btn primary" :disabled="busy||(role==='sys_admin'&&!tenantForAudit)" @click="verify"><ShieldCheck :size="17"/> Kiểm tra sổ cái</button><div v-if="auditResponse" class="notice-inline" :class="auditResponse.valid?'':'notice-danger'">{{auditResponse.valid?'Chuỗi băm hợp lệ':'Phát hiện sai lệch'}} · Đã kiểm {{auditResponse.checked}} mục</div><p class="muted">Chuỗi băm giúp phát hiện sửa đổi dữ liệu, không phải chữ ký số pháp lý hoặc blockchain.</p></div></div>
 <div v-else-if="section==='feedback'" class="sections-two"><div class="light-form" v-if="role==='citizen'"><h3>Đánh giá trải nghiệm</h3><p class="muted">Góp ý để cải thiện trải nghiệm sử dụng bản demo.</p><label class="field-label">Mức hài lòng<select v-model.number="feedbackScore"><option v-for="n in 5" :key="n" :value="n">{{n}} / 5 sao</option></select></label><label class="field-label">Ý kiến<textarea v-model="comment" rows="5" placeholder="Góp ý của bạn..."></textarea></label><button class="btn primary" :disabled="busy" @click="sendFeedback"><Star :size="17"/> Gửi đánh giá</button></div><div v-else class="light-form"><h3>Tổng hợp đánh giá</h3><p>{{feedbackSummary?.count??'Chỉ lãnh đạo và quản trị viên được xem báo cáo tổng hợp.'}} lượt phản hồi</p><strong v-if="feedbackSummary">Điểm trung bình: {{feedbackSummary.avg_rating??'Chưa có dữ liệu'}}</strong></div></div>
 <div v-else-if="section==='notifications'" class="notification-rows notification-large"><div><AlertTriangle class="danger-text" :size="23"/><span>{{stats.overdue||0}} hồ sơ quá hạn cần theo dõi</span></div><div><CalendarDays class="orange-text" :size="23"/><span>{{stats.processing||0}} hồ sơ đang xử lý</span></div><div><CheckCircle2 class="green-text" :size="23"/><span>{{stats.completed||0}} hồ sơ đã có kết quả/được đóng</span></div><p class="muted">Gửi email, SMS và tự động nâng cấp cảnh báo thuộc lộ trình tiếp theo.</p></div>
 <div v-else-if="section==='settings'" class="light-form"><h3>Thông tin phiên đăng nhập</h3><p><strong>Vai trò:</strong> {{user.role}}</p><p><strong>Tài khoản:</strong> {{user.name}}</p><p><strong>Đơn vị:</strong> {{user.tenant_id||'Nhiều đơn vị (quyền tổng hợp)'}}</p><p><strong>Giới hạn:</strong> Không sử dụng dữ liệu thật trong môi trường mô phỏng.</p></div>
 <div v-else class="empty-state"><Info :size="42"/><h3>Chức năng đang ở mức đặc tả</h3><p>Mục này chưa có xử lý nghiệp vụ được kiểm chứng; hãy xem bảng 60 chức năng để theo dõi tiến độ.</p></div>
 <div v-if="notice" class="success-message section-message">{{notice}}</div><p v-if="error" class="error-block section-message">{{error}}</p>
 </div>
</template>
